for name, claim, quote, pd, st, extra in F:
    args = ["python", "../../../../tools/facts.py", "add", "--prefix", "V", "--name", name, "--claim", claim, "--quote", quote, "--page-date", pd, "--status", st]
    for k in ("visa", "field", "value", "note"):
        if k in extra:
            args += ["--" + k, extra[k]]
    r = subprocess.run(args, capture_output=True, text=True, encoding="utf-8")
    out = (r.stdout.strip() or r.stderr.strip()[-220:])
    print(out, "|", claim[:80])
